const targetPageId = '1096244530243584';
const match = $input.all().find(item => item.json.id === targetPageId);
if (!match) {
  throw new Error('Facebook Page ID ' + targetPageId + ' was not found in the list of Pages this account manages (GET /me/accounts). Check the Page ID in this node, and confirm the Facebook user connected to the credential is an admin of that Page.');
}
return [{ json: { pageId: match.json.id, pageAccessToken: match.json.access_token, pageName: match.json.name } }];
